const rupee=n=>n==null?'—':'₹'+Math.round(Number(n)).toLocaleString('en-IN');
const storageKey='jobmitra.candidate.search.prototype.v1';
const icon={pin:'<circle cx="12" cy="11" r="3"/><path d="M20 11c0 5-8 11-8 11S4 16 4 11a8 8 0 0 1 16 0Z"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18"/>',check:'<path d="m5 12 4 4L19 6"/>'};
const svg=(name,size=13)=>`<svg aria-hidden="true" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">${icon[name]||''}</svg>`;
const dateNow=()=>new Date().toISOString();
const candidates=structuredClone(native.people),jobs=structuredClone(native.jobs);
let state={pools:native.pools(),events:native.snapshot.events.map(e=>({event:e.event_type,candidateId:String(e.candidate_id),jobId:String(e.job_id),at:e.created_at})),createdCandidates:[],profileEdits:{},officeVisits:native.historyActivities('OFFICE_VISIT'),jobSearchRequests:native.historyActivities('JOB_SEARCH_REQUEST')},tab='search',matchMode='any',selectedCandidate=null,selectedJob=jobs.find(j=>j.status==='ACTIVE')?.id||'',poolJob=jobs.find(j=>j.status==='ACTIVE')?.id||'',currentResults=[];
function save(){state.selectedCandidate=selectedCandidate;state.selectedJob=selectedJob;state.poolJob=poolJob;}
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3800)}
function candidate(id){return candidates.find(x=>x.id===id)}
function job(id){return jobs.find(x=>x.id===id)}
function abbreviate(s){return String(s||'?').split(' ').slice(0,2).map(x=>x[0]).join('').toUpperCase()}
function expLabel(years){if(years==null)return 'Experience not recorded';const months=Math.round(Number(years)*12),y=Math.floor(months/12),m=months%12;return [y?y+' yr':'',m?m+' mo':''].filter(Boolean).join(' ')||'Fresher'}
function money(c){if(!c.salary||c.salary.amount==null)return 'Not recorded';let value=String(c.salary.amount);if(/[eE]/.test(value))value=Number(value).toLocaleString('en-IN',{useGrouping:false,maximumFractionDigits:20});const [whole,fraction]=value.split('.'),head=whole.slice(0,-3),amount=whole.length>3?head.replace(/\B(?=(\d{2})+(?!\d))/g,',')+','+whole.slice(-3):whole;return '₹'+amount+(fraction?'.'+fraction:'')+' / '+(c.salary.period==='MONTHLY'?'month':c.salary.period==='ANNUAL'?'year':'period not recorded')+' ('+String(c.salary.basis||'UNKNOWN').replace('_','-').toLowerCase()+')';}
function norm(s){return String(s??'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim()}
function keywords(){const q=$('#query').value.trim();if(!q)return[];if(/[,;]/.test(q))return q.split(/[,;]+/).map(s=>s.trim()).filter(Boolean);if(candidates.some(c=>matchesText(c,q)))return [q];const words=q.split(/\s+/).filter(x=>x.length>1&&!['and','with','for','or','the'].includes(x.toLowerCase()));return words.length?words:[q]}

function profileExtraSearchText(c){const extra=c.extraProfile||{};return [extra.employment_history,extra.certifications,extra.projects,extra.achievements,extra.qualifications].map(x=>Array.isArray(x)?x.join(' '):(x||'')).join(' ')}
function persistCandidateChanges(){throw Error('Use the canonical service adapter.');}
function matchesText(c,term){const hay=norm(`${c.name} ${c.title} ${(c.skills||[]).join(' ')} ${c.summary} ${c.employer} ${c.education} ${profileExtraSearchText(c)}`);const t=norm(term);if(hay.includes(t))return true;const aliases={gst:['gst filing','gst returns','gst compliance','gst return filing','gst audit'],tally:['tally prime','tally erp 9'],tds:['tds returns','tds compliance'],esi:['esic'],payroll:['salary processing','monthly payroll'],amazon:['amazon seller central']};return (aliases[t]||[]).some(v=>hay.includes(norm(v)))}
 function salaryStatus(c){const min=validRange('#minSalary'),max=validRange('#maxSalary');if(min===null&&max===null)return 'not-filtered';if(!c.salary)return 'unknown';const basis=$('#salaryBasis').value;if(basis!=='ANY'&&c.salary.basis!==basis)return 'non-comparable';const goal=$('#salaryPeriod').value;const val=c.salary.amount*(c.salary.period===goal?1:c.salary.period==='ANNUAL'?1/12:12);return (min===null||val>=min)&&(max===null||val<=max)?'within':'over'}
