function experienceStatus(c){const min=validRange('#expMin'),max=validRange('#expMax');if(min===null&&max===null)return 'not-filtered';if(c.years==null)return 'unknown';return (min===null||c.years>=min)&&(max===null||c.years<=max)?'within':'outside'}
