async function search(){return native.run(async()=>{const version=++native.version;const query=new URLSearchParams({keywords:$('#query').value,location:$('#location').value,match:matchMode==='all'?'ALL':'ANY',salary_period:$('#salaryPeriod').value,salary_basis:$('#salaryBasis').value==='ANY'?'INDICATIVE':$('#salaryBasis').value,sort:$('#sort').value,page_size:100});for(const [id,name] of [['expMin','experience_min'],['expMax','experience_max'],['minSalary','salary_min'],['maxSalary','salary_max'],['notice','max_notice_days']])if($('#'+id).value!=='')query.set(name,$('#'+id).value);for(const [id,name] of [['unknownExp','include_unknown_experience'],['unknownSalary','include_unknown_salary'],['unknownNotice','include_unknown_notice']])query.set(name,String($('#'+id).checked));if($('#availability').value)query.set('availability',({'Available':'AVAILABLE','To confirm':'TO_CONFIRM','Unavailable':'UNAVAILABLE'})[$('#availability').value]||'TO_CONFIRM');let page=1,items=[],data;do{query.set('page',page++);data=await native.api('/api/v12/approved/search?'+query);items.push(...data.items);}while(items.length<data.total);if(version!==native.version)return;currentResults=items.map(r=>({...candidate(String(r.id)),salaryFilter:salaryStatus(candidate(String(r.id))),expFilter:experienceStatus(candidate(String(r.id)))}));if(selectedCandidate&&!currentResults.some(c=>c.id===selectedCandidate))selectedCandidate=null;$('#resultCount').textContent=`${data.total} Candidate${data.total===1?'':'s'} Found`;$('#resultExplain').textContent='Canonical candidate profiles · Based on professional evidence';renderResults();renderDetails();},toast);}
function renderResults(){const el=$('#resultsList');const terms=keywords();if(!currentResults.length){el.innerHTML=`<div class="empty"><h3>No matching profiles found</h3><p>Try relaxing salary, experience or keyword filters. Unknown salary and experience can be included.</p><button class="btn primary" id="emptyClear" type="button">Clear all filters</button></div>`;$('#emptyClear').addEventListener('click',resetFilters);return;}
el.innerHTML=currentResults.map(c=>{const matched=terms.filter(t=>matchesText(c,t));const memberships=Object.entries(state.pools).filter(([jid,v])=>v[c.id]&&job(jid)?.status==='ACTIVE');const signal=c.salaryFilter==='non-comparable'?'Salary basis needs review':c.salaryFilter==='unknown'?'Salary not recorded':c.expFilter==='unknown'?'Experience not recorded':'';return `<article class="candidate-card ${c.id===selectedCandidate?'selected':''}" data-candidate="${c.id}" tabindex="0" role="button" aria-label="View ${escapeHTML(c.name)} candidate details"><div class="candidate-avatar ${c.tone}">${abbreviate(c.name)}</div><div class="candidate-details"><h3>${escapeHTML(c.name)}</h3><div class="role">${escapeHTML(c.title)}</div><div class="meta"><span>${svg('pin')} ${escapeHTML(c.location)}</span><span>${svg('briefcase')} ${escapeHTML(expLabel(c.years))}</span><span>${escapeHTML(c.salary?money(c):'Expected salary unknown')}</span></div><div class="skills">${[...(c.skills||[])].sort((a,b)=>Number(terms.some(x=>norm(b).includes(norm(x))))-Number(terms.some(x=>norm(a).includes(norm(x))))).slice(0,5).map(s=>`<span class="skill ${matched.some(x=>norm(s).includes(norm(x)))?'matched':''}">${escapeHTML(s)}</span>`).join('')}</div>${signal?`<div class="smallinfo">⚑ ${escapeHTML(signal)}</div>`:''}</div><div class="candidate-action"><span class="matchedbadge ${terms.length?'':'neutral'}">${terms.length?`${matched.length}/${terms.length} terms`:'View profile'}</span>${memberships.length?`<span class="addbadge">In ${memberships.length} active JD${memberships.length!==1?'s':''}</span>`:''}${window.JobmitraUnifiedCompanies?.getEligibility?.(c.id)?.status==='JOINED'?'<span class="addbadge" style="background:#ffe9eb;color:#ad2435">Placed · Not eligible</span>':window.JobmitraUnifiedCompanies?.getEligibility?.(c.id)?.status==='SELECTED'?'<span class="addbadge" style="background:#fff0d4;color:#905b10">Selected · On hold</span>':''}<button type="button" class="btn tiny outline" data-open-candidate="${c.id}">View Details →</button></div></article>`}).join('');
$$('[data-candidate]',el).forEach(card=>{card.addEventListener('click',()=>selectCandidate(card.dataset.candidate));card.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectCandidate(card.dataset.candidate)}})});$$('[data-open-candidate]',el).forEach(b=>b.addEventListener('click',e=>{e.stopPropagation();selectCandidate(b.dataset.openCandidate)}));}
function selectCandidate(id){native.candidateDesk.remember();selectedCandidate=id;save();renderResults();renderDetails();$('#candidateWorkspace').classList.add('has-selection');$('#detailPanel').classList.add('mobile-open');$('#detailUnderlay').classList.add('mobile-open');native.candidateDesk.opened();if(window.matchMedia('(max-width:1160px)').matches){$('#detailPanel').scrollTop=0}}
