 function candidateJDHistoryRecords(id){return native.histories(id);}
// JD history imports from older ATS versions use different stage keys.
// Translate keys for display only; never fabricate an action or interview event.
const STAGE_ALIASES={
  CANDIDATE_POOL:'POOL',POOL:'POOL',
  CANDIDATE_CONTACT:'CONTACT',CONTACT:'CONTACT',
  JOBMITRA_SCREENING:'SCREENING',SCREENING:'SCREENING',
  COMPANY_SUBMISSION:'COMPANY_SUBMISSION',
  COMPANY_INTERVIEW:'COMPANY_INTERVIEW',
  SELECTED_BY_COMPANY:'SELECTED',SELECTED:'SELECTED',
  JOINED:'JOINED',REJECTED:'NOT_SELECTED',NOT_SELECTED:'NOT_SELECTED'
};
function normalizedJDStage(k,rounds=[]){
  const raw=String(k||'').trim();
  if(!raw)return null;
  if(raw.startsWith('ROUND:'))return raw;
  if(rounds.some(r=>r.id===raw))return 'ROUND:'+raw;
  return STAGE_ALIASES[raw.toUpperCase()]||raw;
}
const jdHistoryLabel=key=>({
  POOL:'Candidate Pool',CONTACT:'Candidate Contact',SCREENING:'Jobmitra Screening',
  COMPANY_SUBMISSION:'Company Submission',COMPANY_INTERVIEW:'Company Interview',
  SELECTED:'Selected by Company',JOINED:'Joined',NOT_SELECTED:'Not Selected',NOT_JOINED:'Not Joined',SELECTION_CANCELLED:'Selection Cancelled'
}[normalizedJDStage(key)]||key||'Unknown stage');
const jdStageName=(key,rounds=[])=>{
  const normalized=normalizedJDStage(key,rounds);
  if(normalized?.startsWith('ROUND:'))return rounds.find(r=>r.id===normalized.slice(6))?.name||'Archived company round';
  return jdHistoryLabel(normalized);
};
function jdProgressHTML(record){
  const rounds=record.rounds||[];
  const seq=[['POOL','Pool'],['CONTACT','Contact'],['SCREENING','Screening'],['COMPANY_SUBMISSION','Submission'],
    ...rounds.filter(x=>x.active||String(record.stage)==='ROUND:'+x.id).map(r=>['ROUND:'+r.id,r.name])];
  // Legacy records can be at a non-specific company-interview stage.
  if(normalizedJDStage(record.stage,rounds)==='COMPANY_INTERVIEW')seq.push(['COMPANY_INTERVIEW','Company Interview']);
  seq.push(['SELECTED','Selected'],['JOINED','Joined']);
  const current=normalizedJDStage(record.stage,rounds);
  const rejection=normalizedJDStage(record.rejection?.stageKey||record.rejection?.fromKey,rounds);
  const stopped=current==='NOT_SELECTED',at=stopped?rejection:current;
  let last=seq.findIndex(x=>x[0]===at);
  if(last<0){
    const ev=(record.journey||[]).map(e=>normalizedJDStage(e.toKey||e.fromKey,rounds));
    const idxs=ev.map(k=>seq.findIndex(x=>x[0]===k)).filter(i=>i>=0);
    last=idxs.length?Math.max(...idxs):-1;
  }
  return `<div class="jd-track" aria-label="Recruitment progress for ${escapeHTML(record.title)}">${seq.map(([s,label],i)=>{
    const onStage=i===last,past=last>=0&&i<last,failed=onStage&&stopped;
    const cls=failed?'rejected':onStage?'current':past?'reached':'';
    const sub=failed?'Not selected here':onStage?'Current position':past?'Reached / passed':'Not reached';
    return `<div class="jd-track-stage ${cls}"><span class="jd-track-node">${failed?'×':past?'✓':onStage?'●':'·'}</span><b>${escapeHTML(label)}</b><small>${sub}</small></div>`;
  }).join('')}</div>${last<0?'<p class="profile-v9-muted">This older stage is not fully mapped; historical events are retained below.</p>':''}`;
}

function jdEventsHTML(record){
   const events=[...(record.journey||[])].sort((a,b)=>(Date.parse(b.at)||0)-(Date.parse(a.at)||0));
   if(!events.length)return '<div class="jd-empty-history">No recorded activity yet. Stage reach alone does not establish interview attendance.</div>';
   return `<div class="jd-event-list">${events.map(e=>{
     const type=e.type==='REJECTED'?'Not selected':e.type==='MOVED'?'Stage advanced':e.type==='ADDED'?'Added to JD Pool':e.type==='FEEDBACK'?'Feedback recorded':e.type==='INTERVIEW_SCHEDULED'?'Interview scheduled':e.type==='MILESTONE'?'Milestone updated':e.type||'Activity';
     const desc=e.fromName&&e.toName&&e.fromName!==e.toName?`${e.fromName} → ${e.toName}`:e.toName||e.fromName||'';
     const at=e.at?new Date(e.at).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'}):'Date not recorded';
     return `<div class="jd-event ${e.type==='REJECTED'?'rejected':e.type==='MOVED'?'move':''}"><span class="jd-event-dot"></span><div><b>${escapeHTML(type)}</b><time>${escapeHTML(at)}</time><p>${escapeHTML(desc)}</p>${e.feedback?`<div class="jd-event-note">${escapeHTML(e.feedback)}${e.feedbackSource?' · '+escapeHTML(e.feedbackSource):''}</div>`:''}</div></div>`;
   }).join('')}</div>`;
 }

