async function downloadCandidateDocument(id,cid){return native.run(async()=>{await native.authorize();if(String(id).startsWith('parsed:')){const data=await native.api(`/api/v12/approved/candidates/${cid}/parsed/${String(id).slice(7)}`);const blob=new Blob([data.original_json_text||JSON.stringify(data.payload,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=window.document.createElement('a');a.href=url;a.download='parsed-'+String(id).slice(7)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}else{window.open(`/api/ats-v2/candidates/${cid}/resumes/${id}/download`,'_blank','noopener');}},toast);}
async function validateOriginalDocument(file){
  if(!file||file.size<=0||file.size>10*1024*1024||!(/\.(pdf|docx)$/i.test(file.name)))throw new Error('Choose a PDF or DOCX file between 1 byte and 10 MB');
  const header=new Uint8Array(await file.slice(0,8).arrayBuffer());
  const pdf=file.name.toLowerCase().endsWith('.pdf');
  if(pdf){if(String.fromCharCode(...header.slice(0,5))!=='%PDF-')throw new Error('The selected PDF does not have a PDF file signature');}
  else{if(header[0]!==0x50||header[1]!==0x4b)throw new Error('The selected DOCX is not a ZIP-based document');}
  // The server must perform deeper signature/archive validation before accepting production uploads.
}
