 function docVersions(c){
  const list=Array.isArray(c.resumeVersions)?[...c.resumeVersions]:[];
  if(c.resumeFile&&!list.some(x=>x.name===c.resumeFile))list.push({name:c.resumeFile,at:c.updated||null,imported:true});
  return list.sort((a,b)=>String(b.at||'').localeCompare(String(a.at||'')));
 }
