 function previewParsedJSON(id){
   const c=candidate(id),raw=$('#profileParsedText')?.value||'';if(!c)return;
   if(!raw.trim()||raw.length>256*1024){toast('Paste a valid JSON object under 256 KB.');return;}
   let obj;try{obj=JSON.parse(raw)}catch(e){$('#profileParsedPreview').innerHTML=`<div class="profile-v9-prep" role="alert">Invalid JSON — ${escapeHTML(e.message||'check syntax')}</div>`;return;}
   const parsed=parsedProfessionalFields(obj);
   const extra=c.extraProfile||{};
   const specs=[['title','Job title',c.title,parsed.title],['summary','Professional summary',c.summary,parsed.summary],['employer','Current employer',c.employer,parsed.employer],['education','Education',c.education,parsed.education],['location','Location',c.location,parsed.location]];
   const mergeSkills=[...new Map([...(c.skills||[]),...(parsed.skills||[])].filter(Boolean).map(x=>[x.toLowerCase(),x])).values()];
   if(parsed.skills.length)specs.push(['skills','Skills',(c.skills||[]).join(', '),mergeSkills.join(', ')]);
   for(const [k,label] of [['employment_history','Employment history'],['certifications','Certifications'],['projects','Projects'],['achievements','Achievements'],['qualifications','Qualifications']])if(parsed.extraProfile[k]?.length)specs.push(['extra:'+k,label,(extra[k]||[]).join(' · '),parsed.extraProfile[k].join(' · ')]);
   const entries=specs.filter(x=>x[3]&&x[2]!==x[3]).map(([key,label,before,after])=>({key,label,before,after,status:key==='skills'?'enrich':before?'conflict':'new'}));
   if(!entries.length){$('#profileParsedPreview').innerHTML='<div class="profile-v9-prep">No new supported professional information found. Check keys such as skills, professional_summary, job_title, education or work_experience.</div>';return;}
   const mismatch=parsed.sourceName&&norm(parsed.sourceName)!==norm(c.name);
   pendingParsedPreview={id,parsed,entries,raw,name:$('#profileParsedFile')?.files?.[0]?.name||'Pasted structured JSON',nameMismatch:!!mismatch};
   $('#profileParsedPreview').innerHTML=`${mismatch?`<div class="profile-v9-prep" role="alert" style="background:#fff9ec;border-color:#edd7ac;color:#936821"><b>Name differs:</b> JSON says ${escapeHTML(parsed.sourceName)}, selected profile is ${escapeHTML(c.name)}. Name/phone/email are never auto-updated.<label style="display:block;margin-top:7px;cursor:pointer"><input type="checkbox" id="confirmParsedIdentity"> I verified this JSON belongs to the selected candidate</label></div>`:''}<h3 style="margin:16px 0 6px;font-size:12px">Review suggested profile changes</h3><p class="profile-v9-muted">New fields and skills are selected by default. Conflicting fields require explicit approval.</p><div class="profile-v9-preview-list">${entries.map((e,i)=>`<div class="profile-v9-change"><input type="checkbox" id="parsedApply${i}" data-parsed-apply="${escapeHTML(e.key)}" ${e.status==='new'||e.status==='enrich'?'checked':''}><div><label for="parsedApply${i}">${escapeHTML(e.label)}</label>${e.before?`<p><b>Current:</b> ${escapeHTML(e.before.slice(0,250))}</p>`:''}<p><b>Suggested:</b> ${escapeHTML(e.after.slice(0,450))}</p></div><span class="profile-v9-state ${e.status==='conflict'?'conflict':''}">${e.status==='conflict'?'Review change':e.status==='enrich'?'Add skills':'New'}</span></div>`).join('')}</div><div class="profile-v9-inline"><button type="button" class="btn outline" id="discardParsedPreview">Discard</button><button type="button" class="btn primary" id="confirmParsedApply">Apply selected details</button></div>`;
   $('#discardParsedPreview').onclick=()=>{pendingParsedPreview=null;$('#profileParsedPreview').innerHTML='';};
   $('#confirmParsedApply').onclick=()=>applyParsedJSON(id);
 }
 async function applyParsedJSON(id){return native.run(async()=>{const review=pendingParsedPreview,c=candidate(id);if(!review||!c)throw Error('Preview the parsed JSON first.');if(review.nameMismatch&&!$('#confirmParsedIdentity')?.checked)throw Error('Confirm candidate identity first.');const selected=$$('[data-parsed-apply]:checked').map(x=>x.dataset.parsedApply);if(!selected.length)throw Error('Select at least one field to apply.');const map={title:'job_title',summary:'professional_summary',employer:'current_employer',education:'qualification',location:'current_city',skills:'skills'},changes={},extras={},approved=[];for(const key of selected){if(key.startsWith('extra:')){extras[key.slice(6)]=review.parsed.extraProfile[key.slice(6)];approved.push(key);}else{const field=map[key];if(!field)throw Error('Unsupported field '+key);changes[field]=key==='skills'?[...new Map([...(c.skills||[]),...(review.parsed.skills||[])].map(x=>[x.toLowerCase(),x])).values()]:review.parsed[key];approved.push(field);}}const source=native.snapshot.resumes.find(r=>r.candidate_id===Number(id)&&r.resume_kind==='ORIGINAL'&&r.is_current);if(!source)throw Error('Upload and review the current original resume before applying JSON.');const button=$('#confirmParsedApply');await native.api(`/api/v12/approved/candidates/${id}/parsed`,{idempotency_key:native.key(button),actor_name:await native.authorize(),source_resume_id:source.id,raw_json:review.raw,filename:review.name,approved,changes,professional_extras:extras,identity_confirmed:!review.nameMismatch||!!$('#confirmParsedIdentity')?.checked},'POST',button);pendingParsedPreview=null;await native.refresh();showFullProfilePanel(id,'parsed');await search();toast('Reviewed JSON version saved; only approved professional fields changed.');},toast);}
